#!/bin/zsh
# ab2.sh ACT TAG -> motion/crit/<TAG>_ab2_<ACT>_{opus,argon}.txt : round-2 A/B (round 1 vs round 2 pixel frames, 4x + 1x rows) + silhouette sheet
A=$1; T=$2; C=/Users/waylonhuang/Documents/other/pixelart/REVIEW/exp/2026-10-28_sw_skinned/motion/crit; O=${C:h}/out
IMG=$C/ab2_${A}.png; SIL=$O/sil_${A}_SE.png
Q="You are a strict senior game animator and art director (Pokemon overworld / Sea of Stars / Octopath / PMD sprite standards; Richard Williams mechanics). Image 1 compares two versions of the same ${A} animation of a chibi pixel-art girl (red kimono-dress with big bell sleeves, bob hair + bun + big red bow, thigh-high socks), SE game view, frame by frame with display times: rows 1-2 = A (round 1) at 4x and at TRUE 1x size; rows 3-4 = B (round 2) at 4x and 1x. Image 2 = solid-fill silhouettes of the B key poses at 1x and 4x. Both are raw automatic renders through the same rig and pixel chain; the head now carries the projected master pixels (face detail is not the point). The owner's notes on A: 'gradual improvement; limbs like legs sometimes flicker and disappear; I need movement in the whole body including the head, hair should move, animated not stiff', plus new posing direction: 'more elegant posing, not slouched, confident, feminine' (upright chest, shoulders back and down, soft close arms with soft wrists, narrow but never-crossing feet, pointed toes in the air, light steps; walk = poised bouncy chibi model walk with hip sway; run = light and upright; idle = contrapposto; jump = graceful arc, arched apex). Judge MOTION and POSING, especially at 1x (every motion should be >= 1 px or a deliberate hold). Answer in <= 250 words. First line exactly 'SCORE A: N/10, SCORE B: N/10' (overall, strict: 5 = usable but stiff, 7 = good game quality). Then for B, scores 1-10 on: whole-body motion incl. head, secondary (hair/bow/bun/skirt/sleeves) readable at 1x, timing/holds, elegance/confidence/femininity of posing, no slouch, legs/contacts readability, appeal. Then the top 5 remaining problems in B (frame, body part, direction, amount in 1x px or degrees)."
zsh -ic "claude-as be_system --dangerously-skip-permissions --model claude-opus-5-5 -p \"$Q  Use the Read tool to view these images (absolute paths): $IMG  $SIL . Do not modify any files.\"" > $C/${T}_ab2_${A}_opus.txt 2>/dev/null &
(cd /Users/waylonhuang/Documents/other/pixelart/swordswoman && .venv/bin/python tools/gemini.py ask "$Q Do not inflate." $IMG $SIL > $C/${T}_ab2_${A}_argon.txt 2>&1) &
wait
for w in opus argon; do
  if ! grep -q "SCORE A" $C/${T}_ab2_${A}_${w}.txt; then echo "retry $w"; fi
  echo "$A $w: $(grep -m1 'SCORE A' $C/${T}_ab2_${A}_${w}.txt) ($(wc -c < $C/${T}_ab2_${A}_${w}.txt) bytes)"
done
